macro.command:
// Rajang Claw - advantage on saves vs being knocked prone (MidiQOL isSave)
// Transfer AE registers: flags.midi-qol.onUseMacroName = [isSave]ItemMacro.<this item>

const macroPass = String(args?.[0]?.macroPass ?? "").toLowerCase();
if (macroPass && !macroPass.includes("issave")) return;

const actorDoc = actor ?? item?.actor ?? item?.parent;
const wf = workflow ?? args?.[0]?.workflow;
if (!actorDoc || !wf) return;

const looksProne = (obj) => {
  if (!obj) return false;
  const dump = JSON.stringify(obj).toLowerCase();
  return dump.includes('"prone"') || dump.includes("[prone]") || /\bprone\b/.test(dump);
};

let appliesProne = false;
try {
  const activity = wf.activity;
  const effects = activity?.effects ?? [];
  for (const ref of effects) {
    const eid = ref?._id ?? ref;
    const ef = wf.item?.effects?.get?.(eid)
      ?? wf.item?.effects?.find?.((e) => e.id === eid || e._id === eid);
    const statuses = ef?.statuses;
    const hasProne = statuses?.has?.("prone")
      || [...(statuses ?? [])].includes("prone")
      || looksProne(ef);
    if (ef && hasProne) {
      appliesProne = true;
      break;
    }
  }
  if (!appliesProne && looksProne(activity)) appliesProne = true;
  if (!appliesProne && looksProne(wf.item?.system)) appliesProne = true;
  const desc = String(wf.item?.system?.description?.value ?? "").toLowerCase();
  if (!appliesProne && desc.includes("prone") && (desc.includes("knock") || desc.includes("save"))) {
    appliesProne = true;
  }
} catch (err) {
  console.warn("Rajang Claw prone check failed", err);
}

if (!appliesProne) return;

foundry.utils.setProperty(args[0], "advantage", true);
if (wf) wf.advantage = true;
await actorDoc.setFlag("midi-qol", "advantage.ability.save.all", true);
Hooks.once("midi-qol.RollComplete", async () => {
  try { await actorDoc.unsetFlag("midi-qol", "advantage.ability.save.all"); } catch (_) {}
});
